// Form Trigger 2.2 returns labels; newer versions can return field names.
const canonical = (key) => String(key).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const values = Object.fromEntries(Object.entries($json).map(([key, value]) => [canonical(key), value]));
const get = (...keys) => { for (const key of keys) { const value = values[canonical(key)]; if (value !== undefined && value !== null) return value; } return ''; };
const consent = Object.entries($json).some(([key, value]) => /consent|acknowledge/i.test(key) && Boolean(value));
return [{json:{full_name:get('full_name','full name','name'),email:get('email','email address'),phone:get('phone','phone number'),company:get('company','company name'),category:get('category','inquiry category'),subject:get('subject'),message:get('message'),preferred_contact_method:get('preferred_contact_method','preferred contact method'),consent}}];

// CONFIGURATION: edit plain values here; no credentials belong here.
const cfg = { duplicateWindowHours: 24, defaultOwner: 'Unassigned', requireConsent: true, reminderHours: { Critical: 1, High: 4, Normal: 24, Low: 48 } };
const asText = (value, max) => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ').slice(0, max) : '';
const raw = $json; const full_name = asText(raw.full_name, 120); const email = asText(raw.email, 254).toLowerCase(); const subject = asText(raw.subject, 200); const message = asText(raw.message, 5000); const consent = raw.consent === true || raw.consent === 'true';
if (!full_name || !email || !subject || !message) throw new Error('Full name, email, subject, and message are required.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/u.test(email)) throw new Error('Enter a valid email address.'); if (cfg.requireConsent && !consent) throw new Error('Please acknowledge the privacy notice before submitting.');
const allowed = ['General inquiry','Sales / quotation','Technical support','Existing customer','Partnership','Complaint','Other']; const category = allowed.includes(raw.category) ? raw.category : 'Other'; const text = `${subject} ${message}`.toLowerCase();
const urgent = /\b(urgent|outage|security incident|data loss|legal escalation)\b/u.test(text); let priority = category === 'Partnership' ? 'Low' : 'Normal'; if ((category === 'Complaint' || category === 'Technical support') && urgent) priority = 'High'; if (category === 'Complaint' && /\b(data loss|legal escalation)\b/u.test(text)) priority = 'Critical'; if (category === 'Sales / quotation' && /\b(urgent|asap)\b/u.test(text)) priority = 'High';
const now = new Date(); const submitted_at = now.toISOString(); const inquiry_id = `INQ-${submitted_at.replace(/\D/g,'').slice(0,14)}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
return [{json:{inquiry_id,full_name,email,phone:asText(raw.phone,50),company:asText(raw.company,160),category,subject,message,preferred_contact_method:asText(raw.preferred_contact_method,30),consent,priority,status:'New',assigned_owner:cfg.defaultOwner,source:'n8n-form',submitted_at,last_activity_at:submitted_at,follow_up_due_at:new Date(now.getTime()+cfg.reminderHours[priority]*3600000).toISOString(),reminder_count:0,last_reminder_at:null,notification_state:'pending',processing_state:'stored',error_state:'',duplicate_of:'',dedupe_key:`${email}|${subject.toLowerCase()}|${message.toLowerCase()}`,duplicate_window_start:new Date(now.getTime()-cfg.duplicateWindowHours*3600000).toISOString()}}];

// Elapsed hours after submission, then after each successful stage.
const stages = { Critical: [1, 2, 4], High: [4, 8, 24], Normal: [24, 24, 48], Low: [48, 48, 72] };
const intervals = stages[$json.priority] ?? stages.Normal;
const submitted = Date.parse($json.submitted_at);
const firstDue = new Date(submitted + intervals[0] * 3600000).toISOString();
return [{json:{...$json,follow_up_due_at:firstDue,next_reminder_due_at:firstDue,reminder_stage:0,reminder_count:0,reminder_retry_count:0,last_retry_at:null,last_retry_error:'',delivery_failure_state:'none',escalation_state:'not_escalated',last_notification_outcome:'pending',notification_attempts:0,last_duplicate_at:null,follow_up_intervals_hours:intervals}}];

const maxReminders = 3; const eligibleStatuses = ['New', 'Acknowledged', 'In progress']; const now = Date.now();
return $input.all().map(({json: r}) => {
  const reasons = []; const dueAt = r.next_reminder_due_at ?? r.follow_up_due_at; const stage = Number(r.reminder_stage || 0);
  if (!eligibleStatuses.includes(r.status)) reasons.push('status ' + r.status + ' is paused or complete');
  if (r.processing_state !== 'stored') reasons.push('processing_state is not stored');
  if (r.delivery_failure_state === 'delivery_failed') reasons.push('terminal delivery retry limit reached');
  if (Number(r.reminder_count || 0) >= maxReminders) reasons.push('maximum reminder count reached');
  if (!dueAt || Number.isNaN(Date.parse(dueAt))) reasons.push('next_reminder_due_at is missing or invalid');
  else if (Date.parse(dueAt) > now) reasons.push('next reminder is not due yet');
  return { json: { ...r, next_reminder_due_at: dueAt, reminder_action: stage >= 2 ? 'escalation' : 'reminder', reminder_eligible: reasons.length === 0, reminder_skip_reason: reasons.join('; ') || 'eligible now', reminder_checked_at: new Date(now).toISOString() } };
});
